package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen4Test {

    @Test
    public void testStop_WhenRunning_ShouldSucceed() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        // Act
        stopWatch.stop();

        // Assert
        // Since runningState becomes STATE_STOPPED, calling stop again should throw exception
        try {
            stopWatch.stop();
            Assert.fail("Expected IllegalStateException because stopwatch is already stopped");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }

    @Test
    public void testStop_WhenSuspended_ShouldSucceed() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();

        // Act
        stopWatch.stop();

        // Assert
        // Verify state transition by checking if calling stop again throws exception
        try {
            stopWatch.stop();
            Assert.fail("Expected IllegalStateException because stopwatch is already stopped");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenNotStarted_ShouldThrowException() {
        StopWatch stopWatch = new StopWatch();
        // State is currently STATE_READY (not running and not suspended)
        stopWatch.stop();
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenAlreadyStopped_ShouldThrowException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Act
        stopWatch.stop();
    }

    @Test
    public void testStop_UpdatesStopTime() throws InterruptedException {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        Thread.sleep(10); // Ensure time passes
        stopWatch.stop();

        long timeAfterStop = stopWatch.getTime();
        Assert.assertTrue("Time should be greater than 0", timeAfterStop > 0);
    }
}
